  ?zone brick:hasSubclassOf ?z .
  FILTER (regex(str(?zone), "Perimeter_mid_ZN_1"))
  ?pSensor ref:hasTimeseriesId ?seriesPower ;
           brick:hasProperty ?pProp ;
           brick:isPointOf ?zone .
  ?occSensor ref:hasTimeseriesId ?seriesOcc ;
             brick:isPointOf ?zone .
  ?occProp brick:inDomain brick:OccupancySensor .
}

SELECT ?s WHERE {
  ?z a brick:Zone .
  FILTER (regex(str(?z), "Perimeter_mid_ZN_1"))
  ?pt brick:isPointOf ?z ; ref:hasTimeseriesId ?s .
}

